import { test } from "node:test";
import assert from "node:assert/strict";
import { refuseEnqueue, type OrgLoad } from "../src/admission.ts";

test("allows enqueue when queued is below five times share", () => {
  const load: OrgLoad = { queued: 24, running: 10, share: 5 };
  assert.equal(refuseEnqueue(load), false);
});

test("refuses enqueue when queued equals five times share", () => {
  const load: OrgLoad = { queued: 25, running: 10, share: 5 };
  assert.equal(refuseEnqueue(load), true);
});

test("refuses enqueue when queued exceeds five times share", () => {
  const load: OrgLoad = { queued: 100, running: 10, share: 5 };
  assert.equal(refuseEnqueue(load), true);
});

test("allows enqueue when share is zero and queue is empty", () => {
  const load: OrgLoad = { queued: 0, running: 0, share: 0 };
  assert.equal(refuseEnqueue(load), false);
});

test("refuses enqueue when queue has jobs but share is zero", () => {
  const load: OrgLoad = { queued: 1, running: 0, share: 0 };
  assert.equal(refuseEnqueue(load), true);
});

